#include <iostream>
#include <string>

template<typename T1, typename T2>
auto genericMax(const T1& a, const T2& b) -> decltype((a > b) ? a : b)
{
    return (a > b) ? a : b;
}

int main()
{
    int i = 10;
    double d = 20.75;
    std::string s1 = "NBC";
    std::string s2 = "ABC";

    std::cout << "Max between int and double: " << genericMax(i, d) << std::endl;
    std::cout << "Max between strings: " << genericMax(s1, s2) << std::endl;

    return 0;
}

#include <iostream>
#include <string>

template<typename T>
void selectionSort(T list[], int listSize)
{
    for (int i = 0; i < listSize - 1; i++)
    {
        T currentMin = list[i];
        int currentMinIndex = i;
        for (int j = i + 1; j < listSize; j++)
        {
            if (currentMin > list[j])
            {
                currentMin = list[j];
                currentMinIndex = j;
            }
        }
        if (currentMinIndex != i)
        {
            list[currentMinIndex] = list[i];
            list[i] = currentMin;
        }
    }
}

template<typename T>
void printArray(const T list[], int listSize)
{
    for (int i = 0; i < listSize; i++)
    {
        std::cout << list[i] << (i + 1 < listSize ? " " : "");
    }
    std::cout << std::endl;
}

int main()
{
    int intArr[] = {3, 5, 1, 0, 2, 8, 7};
    selectionSort(intArr, 7);
    printArray(intArr, 7);

    std::string strArr[] = {"Atlanta", "Denver", "Chicago", "Dallas"};
    selectionSort(strArr, 4);
    printArray(strArr, 4);

    return 0;
}
